      "question_id": "Q1",
      "answer": "Eight volumes are listed, though the register preserves nine entries because one ledger appears twice."
    },
    {
      "question_id": "Q2",
      "answer": "Cart 2 delivered the largest number, four volumes; cart 1 and cart 3 each carried two."
    },
    {
      "question_id": "Q3",
      "answer": "The clerk attached a plain buff cross-reference slip, not a new shelf label, when one volume bore another volume's shelf reference."
    },
    {
      "question_id": "Q4",
      "answer": "T. Fenwick, the borough porter, unloaded cart 3; the note does not credit a second person."
    },
    {
      "question_id": "Q5",
      "answer": "Lena Brice of conservation supplied the narrow green bands; they were not taken from the reading-room stock."
    },
    {
      "question_id": "Q6",
      "answer": "Two volumes remained in the review cabinet; the others had been cleared to the returned-ledger shelves."
    }
  ]
}
